"""Owned SNS-to-SQS tracing experiment. No global sampling/encryption changes."""
import datetime, hashlib, json, os, re, subprocess, time, traceback, uuid
from pathlib import Path
import boto3
from botocore.config import Config
from botocore.exceptions import ClientError
ROOT=Path('/home/r/dev/minor/stackd')
OUT=ROOT/'testdata/aws/sns/tracing.json'
PREFIX='stackd-snstrace-'+uuid.uuid4().hex[:10]
ACCOUNT='000000000000'; REGION='us-east-1'
creds=json.loads(subprocess.run(['aws','configure','export-credentials','--format','process'],capture_output=True,text=True,check=True,timeout=30).stdout)
session=boto3.Session(aws_access_key_id=creds['AccessKeyId'],aws_secret_access_key=creds['SecretAccessKey'],aws_session_token=creds.get('SessionToken'),region_name=REGION)
clients={s:session.client(s,config=Config(retries={'total_max_attempts':1},connect_timeout=10,read_timeout=30)) for s in ('sns','sqs','xray','sts')}
del creds
cap={'account':ACCOUNT,'region':REGION,'prefix':PREFIX,'capture_started_ms':int(time.time()*1000),'observations':[],'resources':{'topics':{},'queues':{},'subscriptions':[],'policy_name':PREFIX},'cases':[],'poll_windows':[],'cleanup':[],'independent_cleanup':[],'sources':[{'url':'https://docs.aws.amazon.com/sns/latest/dg/sns-active-tracing.html','retrieved_date':'2026-09-23','claim':'Active/Passive propagation, both standard and FIFO topic support; manual X-Ray resource permission required.'},{'url':'https://docs.aws.amazon.com/xray/latest/devguide/xray-services-sns.html','retrieved_date':'2026-09-23','claim':'SNS active segments and subscriber SQS subsegments; exact-source resource policy actions.'}],'executed_sources':[]}
for path in (Path(__file__),ROOT/'scripts/aws/aws_cli.py',ROOT/'scripts/aws/signed_requests.py'):
    text=path.read_text();cap['executed_sources'].append({'path':str(path),'sha256':hashlib.sha256(text.encode()).hexdigest(),'content':text,'role':'executed probe' if path==Path(__file__) else 'reviewed existing helper convention; SDK transport used for response metadata and trace-header injection'})
actor='arn:aws:iam::'+ACCOUNT+':user/Delegated'
def persist():OUT.write_text(json.dumps(cap,indent=2,default=str)+'\n')
def obs(label,service,operation,parameters=None,header=None,bucket='observations'):
    parameters=parameters or {}; client=clients[service]
    def inject(request,**kwargs):
        if header is not None:request.headers['X-Amzn-Trace-Id']=header
    event='before-sign.'+service+'.'+''.join(w.title() for w in operation.split('-'))
    if header is not None:client.meta.events.register(event,inject)
    started=int(time.time()*1000)
    try:
        output=getattr(client,operation.replace('-','_'))(**parameters); code='Success'
    except ClientError as e:output=e.response;code=output['Error']['Code']
    finally:
        if header is not None:client.meta.events.unregister(event,inject)
    ended=int(time.time()*1000);meta=output.pop('ResponseMetadata',{})
    row={'label':label,'caller_account':ACCOUNT,'actor_arn':actor,'service':service,'operation':operation,'input':parameters,'result':{'code':code,'output':output,'http_status':meta.get('HTTPStatusCode'),'request_id':meta.get('RequestId')},'request_started_ms':started,'response_observed_ms':ended}
    if operation in ('publish','publish-batch'):row['sent_http_trace_headers']={} if header is None else {'X-Amzn-Trace-Id':header}
    cap[bucket].append(row);persist();return row

def success(row):
    if row['result']['code']!='Success':raise RuntimeError(row['label']+': '+str(row['result']))
    return row['result']['output']
def fresh():return '1-'+format(int(time.time()),'08x')+'-'+uuid.uuid4().hex[:24]
def header(root,parent=None,sampled='1'):return 'Root='+root+';Parent='+(parent or uuid.uuid4().hex[:16])+';Sampled='+sampled

def deliver(kind,case):
    start=int(time.time()*1000);deadline=time.monotonic()+40;found={q:[] for q in ('raw','wrapped')}; expected=len(case['message_ids'])
    while time.monotonic()<deadline and any(len(v)<expected for v in found.values()):
        for mode in found:
            if len(found[mode])>=expected:continue
            q=cap['resources']['queues'][kind+'-'+mode]
            row=obs('receive-'+case['label']+'-'+mode,'sqs','receive-message',{'QueueUrl':q['url'],'MaxNumberOfMessages':10,'WaitTimeSeconds':2,'MessageSystemAttributeNames':['All'],'MessageAttributeNames':['All']})
            for m in success(row).get('Messages',[]):
                found[mode].append(m)
                obs('ack-'+case['label']+'-'+mode,'sqs','delete-message',{'QueueUrl':q['url'],'ReceiptHandle':m['ReceiptHandle']})
    case['deliveries']=found;case['delivery_window']={'started_ms':start,'ended_ms':int(time.time()*1000),'deadline_seconds':40,'expected_per_queue':expected,'received_per_queue':{k:len(v) for k,v in found.items()}};persist()

def publish(kind,phase,name,hdr,batch=False,attributes=None):
    label=kind+'-'+phase+'-'+name+('-batch' if batch else '')
    case={'label':label,'kind':kind,'phase':phase,'header':hdr,'batch':batch,'trace_ids':re.findall(r'Root=(1-[0-9a-f]{8}-[0-9a-f]{24})',hdr or '')}
    topic=cap['resources']['topics'][kind]
    entries=[{'Id':str(i),'Message':json.dumps({'probe':PREFIX,'case':label,'entry':i})} for i in range(2 if batch else 1)]
    for e in entries:
        if kind=='fifo':e.update(MessageGroupId='trace-probe',MessageDeduplicationId=uuid.uuid4().hex)
        if attributes:e['MessageAttributes']=attributes
    if batch:params={'TopicArn':topic,'PublishBatchRequestEntries':entries}
    else:params={'TopicArn':topic,**{k:v for k,v in entries[0].items() if k!='Id'}}
    row=obs(label,'sns','publish-batch' if batch else 'publish',params,hdr)
    out=success(row);case['message_ids']=[x['MessageId'] for x in out.get('Successful',[])] if batch else [out['MessageId']]
    case['publish_request_id']=row['result']['request_id'];case['published_ms']=row['response_observed_ms'];cap['cases'].append(case);persist();deliver(kind,case);return case

def tracepoll(label,cases,duration,require_sns=False):
    ids=sorted(set(t for c in cases for t in c['trace_ids']));start=int(time.time()*1000);deadline=time.monotonic()+duration;attempts=0;seen=set();sns_seen=set()
    while True:
        attempts+=1
        for i in range(0,len(ids),5):
            row=obs(label+'-'+str(attempts)+'-'+str(i),'xray','batch-get-traces',{'TraceIds':ids[i:i+5]})
            for t in success(row).get('Traces',[]):
                seen.add(t['Id'])
                for s in t.get('Segments',[]):
                    doc=json.loads(s['Document'])
                    if doc.get('origin')=='AWS::SNS::Topic':sns_seen.add(t['Id'])
        if (require_sns and sns_seen) or time.monotonic()>=deadline:break
        time.sleep(min(10,max(0,deadline-time.monotonic())))
    cap['poll_windows'].append({'label':label,'trace_ids':ids,'started_ms':start,'ended_ms':int(time.time()*1000),'deadline_seconds':duration,'attempts':attempts,'trace_ids_seen':sorted(seen),'sns_trace_ids_seen':sorted(sns_seen),'absence_scope':'Only these exact roots within this window; no claim of permanent absence.'});persist();return sns_seen

def policy(effect='Allow'):
    return {'Version':'2012-10-17','Statement':[{'Sid':'OwnedSNSAccess','Effect':effect,'Principal':{'Service':'sns.amazonaws.com'},'Action':['xray:PutTraceSegments','xray:GetSamplingRules','xray:GetSamplingTargets'],'Resource':'*','Condition':{'StringEquals':{'aws:SourceAccount':ACCOUNT},'ArnEquals':{'aws:SourceArn':list(cap['resources']['topics'].values())}}}]}
policy_created=False
try:
    ident=success(obs('identity','sts','get-caller-identity'));assert ident['Account']==ACCOUNT;actor=ident['Arn']
    obs('xray-policies-before','xray','list-resource-policies',{})
    for kind in ('standard','fifo'):
        attrs={'FifoTopic':'true','ContentBasedDeduplication':'false'} if kind=='fifo' else {}
        topic=success(obs('create-'+kind,'sns','create-topic',{'Name':PREFIX+('-fifo.fifo' if kind=='fifo' else '-std'),'Attributes':attrs}))['TopicArn'];cap['resources']['topics'][kind]=topic;persist()
        obs('default-'+kind,'sns','get-topic-attributes',{'TopicArn':topic})
        for value in ('Active','Passive','active','PASSIVE','', 'Invalid'):
            obs('tracing-'+kind+'-'+repr(value),'sns','set-topic-attributes',{'TopicArn':topic,'AttributeName':'TracingConfig','AttributeValue':value})
            obs('read-tracing-'+kind+'-'+repr(value),'sns','get-topic-attributes',{'TopicArn':topic})
        for mode in ('raw','wrapped'):
            name=PREFIX+'-'+kind+'-'+mode+('.fifo' if kind=='fifo' else '')
            qa={'FifoQueue':'true'} if kind=='fifo' else {}
            url=success(obs('create-queue-'+kind+'-'+mode,'sqs','create-queue',{'QueueName':name,'Attributes':qa}))['QueueUrl'];cap['resources']['queues'][kind+'-'+mode]={'name':name,'url':url};persist()
            actual=success(obs('queue-attributes-'+kind+'-'+mode,'sqs','get-queue-attributes',{'QueueUrl':url,'AttributeNames':['All']}))['Attributes'];arn=actual['QueueArn'];cap['resources']['queues'][kind+'-'+mode]['arn']=arn
            qp={'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'sns.amazonaws.com'},'Action':'sqs:SendMessage','Resource':arn,'Condition':{'ArnEquals':{'aws:SourceArn':topic}}}]}
            success(obs('queue-policy-'+kind+'-'+mode,'sqs','set-queue-attributes',{'QueueUrl':url,'Attributes':{'Policy':json.dumps(qp)}}))
            sub=success(obs('subscribe-'+kind+'-'+mode,'sns','subscribe',{'TopicArn':topic,'Protocol':'sqs','Endpoint':arn,'ReturnSubscriptionArn':True,'Attributes':{'RawMessageDelivery':str(mode=='raw').lower()}}))['SubscriptionArn'];assert sub.startswith(topic+':');cap['resources']['subscriptions'].append(sub);persist()
            obs('confirmed-'+kind+'-'+mode,'sns','get-subscription-attributes',{'SubscriptionArn':sub})
    # A direct caller-owned segment makes X-Ray ingestion/read access a positive control,
    # but is never represented as an SNS-emitted segment.
    root=fresh();parent=uuid.uuid4().hex[:16];now=time.time()
    doc={'trace_id':root,'id':parent,'name':PREFIX+'-publisher-control','start_time':now-.1,'end_time':now,'metadata':{'probe':{'kind':'explicit caller instrumentation'}}}
    success(obs('publisher-segment-positive-control','xray','put-trace-segments',{'TraceSegmentDocuments':[json.dumps(doc)]}))
    cap['publisher_control']={'trace_id':root,'parent_id':parent,'document':doc}
    tracepoll('publisher-positive-read',[{'trace_ids':[root]}],30)
    passive=[]
    for kind in ('standard','fifo'):
        for name,sampled in (('absent',None),('sampled-zero','0'),('sampled-one','1')):
            passive.append(publish(kind,'passive',name,None if sampled is None else header(fresh(),sampled=sampled)))
        passive.append(publish(kind,'passive','invalid-root','Root=invalid;Parent=0123456789abcdef;Sampled=1'))
        passive.append(publish(kind,'passive','sampled-one',header(fresh()),batch=True))
    tracepoll('passive-emission-window',passive,40)
    for kind,topic in cap['resources']['topics'].items():success(obs('activate-'+kind,'sns','set-topic-attributes',{'TopicArn':topic,'AttributeName':'TracingConfig','AttributeValue':'Active'}))
    denied=[]
    for kind in ('standard','fifo'):denied.append(publish(kind,'no-resource-grant','sampled-one',header(fresh())))
    tracepoll('no-resource-grant-window',denied,60)
    success(obs('allow-owned-topic-traces','xray','put-resource-policy',{'PolicyName':PREFIX,'PolicyDocument':json.dumps(policy()),'BypassPolicyLockoutCheck':False}));policy_created=True
    time.sleep(15)
    active=[]
    for kind in ('standard','fifo'):
        for name,sampled in (('absent',None),('sampled-zero','0'),('sampled-one','1')):
            active.append(publish(kind,'active',name,None if sampled is None else header(fresh(),sampled=sampled)))
        for name,h in [('invalid-root','Root=invalid;Parent=0123456789abcdef;Sampled=1'),('invalid-parent','Root='+fresh()+';Parent=invalid;Sampled=1'),('invalid-sampled',header(fresh(),sampled='banana')),('whitespace-extension','Root='+fresh()+'; Parent=0123456789abcdef; Sampled=1;Foo=bar'),('duplicate-sampled',header(fresh(),sampled='0')+';Sampled=1')]:
            active.append(publish(kind,'active',name,h))
        # HTTP context and same-named application attribute are separate namespaces.
        active.append(publish(kind,'active','attribute-precedence',header(fresh()),attributes={'AWSTraceHeader':{'DataType':'String','StringValue':header(fresh())}}))
        for name,sampled in (('absent',None),('sampled-zero','0'),('sampled-one','1')):
            active.append(publish(kind,'active',name,None if sampled is None else header(fresh(),sampled=sampled),batch=True))
    tracepoll('active-emission-window',active,90)
    # Repair is already a cold deny -> scoped allow transition. Explicit deny tests
    # resource-policy grammar separately without altering any unrelated statement.
    row=obs('explicit-deny-owned-topic-traces','xray','put-resource-policy',{'PolicyName':PREFIX,'PolicyDocument':json.dumps(policy('Deny')),'BypassPolicyLockoutCheck':False})
    if row['result']['code']=='Success':
        time.sleep(15);negative=[publish('standard','explicit-deny','sampled-one',header(fresh()))];tracepoll('explicit-deny-window',negative,60)
        success(obs('repair-owned-topic-traces','xray','put-resource-policy',{'PolicyName':PREFIX,'PolicyDocument':json.dumps(policy()),'BypassPolicyLockoutCheck':False}));time.sleep(15)
        repaired=[publish('standard','repaired','sampled-one',header(fresh()))];tracepoll('repair-emission-window',repaired,90)
    cap['capture_completed_ms']=int(time.time()*1000)
